Matching Ayahs
- = アリフ、ラーム、ミーム。2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = これらの者は、主からの正しい導きの上にあり、これらの者は成功する者である。2:5; 31:5
- = イスラエルの子らよ、われが汝らに授けた恵みと、われが汝らを諸国民（世界）より優れた者としたことを思い出せ。2:47; 2:122
- = それは過ぎ去った民族である。彼らには彼らの稼ぎが、汝らには汝らの稼ぎがある。汝らは彼らの行いについて問われることはない。2:134; 2:141
- = 彼らはその中に永遠に住む。彼らに対しては懲罰が軽減されず、また猶予も与えられない。2:162; 3:88
- = 但し、その後悔い改めて（自らを）正す者は別である。実にアッラーは寛容にして慈悲深くあられる。3:89; 24:5
- = しかるに不信仰であり、わが印を否定する者、これらの者は地獄の仲間である。5:10; 5:86
- = 彼らの主の印の中から一つの印が彼らに到来するたびに、彼らはそれから背を向ける。6:4; 36:46
- = あなた以前にも使者たちは嘲笑された。しかし嘲笑していた者たちは、自分たちが嘲笑していたもので包囲された。6:10; 21:41
- = 言え、「もし私が主に背くならば、私は偉大な日の懲罰を恐れる」と。6:15; 39:13
- = そこで地震が彼らを襲い、彼らは自分の家の中でうつ伏せになって死んだ。7:78; 7:91
- = そこで彼（ムーサー）は自分の杖を投げると、見よ、それは明らかな蛇となった。7:107; 26:32
- = そして彼は自分の手を差し出すと、見よ、それは見る者にとって白く（輝いて）いた。7:108; 26:33
- = 彼らは言った、「われらは世界の主を信じた。」7:121; 26:47
- = ムーサーとハールーンの主を。7:122; 26:48
- = そしてわれは彼らに猶予を与える。実にわが計画は確固たるものである。7:183; 68:45
- = かれこそは、その使徒を導きと真理の宗教とともに遣わされた方である。それは、たとえ多神教徒が嫌っても、それをすべての宗教の上に勝利させるためである。9:33; 61:9
- = 預言者よ、不信仰者と偽信者と戦い、彼らに厳しく対処せよ。彼らの住まいは地獄である。何と忌まわしい行き先であろうか。9:73; 66:9
- = 彼らは言う、「この約束はいつなのか、もしあなたがたが真実であるならば。」10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = またわれはムーサーを、わが印と明らかな権威とともに遣わした。11:96; 40:23
- = またわれはムーサーに書物を授けたが、それについて意見の相違が生じた。あなたの主からの先行する言葉がなかったならば、彼らの間で裁きが下されていたであろう。そして彼らはそれについて深い疑念の中にある。11:110; 41:45
- = それはアッラーにとって難しいことではない。14:20; 35:17
- = 「われが彼を完全に形作り、わが霊を彼に吹き込んだならば、あなたがたは彼の前にひれ伏せ。」15:29; 38:72
- = そこで天使たちは全員が一斉にひれ伏した。15:30; 38:73
- = （アッラーは）仰せられた、「それならばここから出て行け。あなたは確かに追放された者である。」15:34; 38:77
- = （イブリースは）言った、「主よ、それならば彼らが復活される日まで、私に猶予をお与えください。」15:36; 38:79
- = （アッラーは）仰せられた、「あなたは確かに猶予を与えられた者の一人である。」15:37; 38:80
- = 定められた時まで。」15:38; 38:81
- = 彼らの中のあなたの選ばれたしもべたちを除いて。15:40; 38:83
- = 実に敬虔な者たちは、庭園と泉の中にいるであろう。15:45; 51:15
- = 彼（イブラーヒーム）は言った、「では、使者たちよ、あなたがたの用件は何か。」15:57; 51:31
- = 彼らは言った、「われらは罪深い民のところに遣わされた。」15:58; 51:32
- = 信仰し、その信仰を不正によって汚さなかった者たち、これらの者には平安があり、これらの者たちは正しく導かれている。16:42; 29:59
- = 彼らがわれの与えたものに不信心となるように。楽しめ、やがて汝らは知るであろう。16:55; 30:34
- = その後、彼（ズルカルナイン）は（別の）道をたどった。18:89; 18:92
- = フィルアウン（ファラオ）のもとへ行け。実に彼は暴虐であった。20:24; 79:17
- = また彼らは自分の性的部位を守る者たちである。23:5; 70:29
- = 自分の妻たちか、あるいは自分の右手が所有する者（女奴隷）に対しては別である。その場合、彼らは非難されない。23:6; 70:30
- = しかし、それを超えて求める者、これらの者は越境者である。23:7; 70:31
- = また彼らは、預かり物と契約を守る者たちである。23:8; 70:32
- = 彼（ヌーフ）は言った、「主よ、彼らが私を否定したので、私をお助けください。」23:26; 23:39
- = ター、スィーン、ミーム。26:1; 28:1
- = これらは明瞭な書物の節である。26:2; 28:2
- = 実にこれには一つの印がある。しかし彼らの大半は信じなかった。26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = そして実にあなたの主こそは、偉力ならびなく慈愛深くあられる。26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = そしてわれは他の者たちを溺れさせた。26:66; 37:82
- = 実に私は、あなたがたへの信頼すべき使者である。26:107; 26:125; 26:143; 26:162; 26:178
- = だからアッラーを畏れ、私に従え。26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = また私はこれに対してあなたがたに報酬を求めない。私の報酬は世界の主にのみある。26:109; 26:127; 26:145; 26:164; 26:180
- = 庭園と泉の中で。26:147; 44:52
- = 彼らは言った、「あなたはただ魔法にかけられた者の一人だ。」26:153; 26:185
- = しかし彼の妻は別である。われは彼女が後れを取る者たちの一人であると定めた。26:171; 37:135
- = その後、われは他の者たちを破壊した。26:172; 37:136
- = そして彼らの上に（石の）雨を降らせた。警告された者たちへの雨は何と忌まわしいことであったか！26:173; 27:58
- = それで彼らは（わが）懲罰を急がせるのか？26:204; 37:176
- = 礼拝を確立し、ザカートを支払い、来世を確信している者たち。27:3; 31:4
- = また（ムハンマドよ、）彼が彼らを呼び、「あなたがたが主張していた私の『共同者』たちはどこにいるのか」と言う日を思い出せ。28:62; 28:74
- = また我々の先祖たちも（同じく復活するのか）？37:17; 56:48
- = 彼らは互いに近づき合い、問い合うであろう。37:27; 52:25
- = しかし（彼らは）アッラーの選ばれたしもべたちである。37:40; 37:74; 37:128; 37:160
