- 彼らの期限が来たなら、彼らは一刻も遅らせることも早めることもできない。 (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- あなたがたは悪魔の足跡に従ってはならない。本当に彼はあなたがたの公然の敵である。 (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- また人々の中には、知識もなくアッラーについて議論する者がある。 (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- アッラーは、御心のままにそれを与えられる。アッラーは偉大な恩恵の主であられる。 (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- 各人は自分が行ったことに対して完全に報いられ、彼らは不当に扱われない。 (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- アッラーが禁じた命を、正当な理由なく殺してはならない。 (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- かれが一つのことを決められるとき、ただ「あれ」と言われるだけで。 (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- あなたがたは地獄の門に入れ。そこに永遠に住むのである。高慢な者の住まいは何と惨めなことか。 (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- あなたは、啓典の一部を与えられた者たちを見なかったのか。 (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- 彼らには、その下を川が流れる楽園があり、そこに永遠に住むのである。 (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- 我が民よ、あなたがたは自分の立場に従って行動しなさい。私も行動する。やがてあなたがたは知るであろう。 (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- アッラーとその使徒に反抗する者には、地獄の火があり、そこに永遠に住むのである。 (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- われらは彼らの心に覆いをかけ、彼らがそれを理解しないようにし、またその耳に重荷を置いた。 (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- われらが警告者を遣わしたどの町でも、その中の裕福な者たちは言った。「本当に我々は。 (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- 彼らは言った。「あなたの主に、私たちのために祈ってください。それが何であるかを私たちに明らかにしてくださるように。」 (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- 彼らは必ず「アッラー」と言うであろう。言え、「称賛はアッラーにこそあれ。」しかし、彼らの大多数は。 (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- 彼の民の答は、「彼らを追い出せ」と言っただけであった。 (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- その下を川が流れ、彼らはそこに永遠に住む。それが偉大な成功である。 (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- これらの者たちは、主からの導きの上にあり、これらの者たちこそ成功者である。 (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- 辱める懲罰が訪れる者、そして永遠の懲罰が降りかかる者。 (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- あなたがたは地上を旅して、嘘呼ばわりした者たちの結末がどうなったかを観察しなさい。 (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- 彼らは自分たちの手が先に送ったもののために、それを永遠に望むことはない。アッラーは不義な者たちをよく知っておられる。 (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- かれは、誰がその道から迷い去ったかを最もよく知っておられ、かれは最もよく知っておられる。 (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- 本当にアッラーは、私の主でありあなたがたの主である。だからかれを崇めなさい。これがまっすぐな道である。 (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- かれは人類に対して恵み深い。しかし、彼らの大多数は感謝しない。 (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- 天と地とその間にあるものは、真理と定められた期間のために創造したに過ぎない。 (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- 彼らを放っておけ、彼らが約束されているその日に会うまで、空虚な論議と遊びにふけらせておけ。 (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- 彼らは信者に会うと「私たちは信じた」と言い、また互いにだけの時には。 (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- 彼らは律法と福音と、主から自分たちに下されたものを実行する。 (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- かれは彼らの前にあるものと後ろにあるものを知っておられる。しかし、彼らはそれを知識で包み尽くすことはできない。 (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- かれは、天と地を六日間で創造された方である。 (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- 本当にその中には、あなたがたへの印がある。もしあなたがたが信者であるなら。 (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- 導きが人々に来たとき、彼らが信仰するのを妨げたものは何か。 (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- 彼らはアッラーに同位者を立て、その道から迷わせようとした。言え、「楽しむがいい。」 (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- 彼らは、自分たちの中から警告者が来たことに驚き、不信仰者は言った。「これは。 (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- 本当にあなたの主は、誰がその道から迷い去ったかを最もよく知っておられる。 (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- 人に見せびらかすために自分の財産を施し、アッラーを信じない者のようなもの。 (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- あなたがたに与えられたものから、その日が来る前に施しなさい。 (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- かれは、天と地にあるものをあなたがたのために従わせられた。 (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- そして、本当に私たちは、あなたがたが私たちを呼ぶことに対して疑念を抱いている。 (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- 本当にあなたの主は、御心のままに sustenance を広げたり狭めたりされる。本当にかれは。 (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- 天と地とその間にあるものの主。もしあなたがたが確信者であるなら。 (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- 私たちはアッラーを信じ、私たちに下されたものと、 (إبراهيم、イスマイル、イスハク、ヤコブと諸部族に) 下されたものを信じる。 (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- 不義な者たちは、激しい叫びに襲われ、彼らは自分の家の中で倒れ伏した。 (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- それらの女性たちが自分自身について行うことについて、あなたがたに罪はない。 (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- あなたの主は、誰がその道から迷い去ったかを最もよく知っておられる。また、かれは。 (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- かれの命令によって、霊（啓示）を、御心にかなうしもべに下される。 (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- またわれらは、マルヤムの子イーサーに明証を与え、聖霊によって彼を強力に支援した。 (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- 復活の日、彼らが争っていたことについて、彼らの間を裁くために。 (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- われらはその町を上下逆さまにし、焼き粘土の石を雨のように降らせた。 (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- あなたが警告しても警告しなくても、彼らにとっては同じである。彼らは信じない。 (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- 人々を差し置いて、もしあなたがたが誠実なら、死を望みなさい。 (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- アッラーを（崇めよ）。あなたがたには、かれ以外に神はない。それでもあなたがたは畏れないのか。 (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- われらが彼らに約束したものの一部をあなたに見せようと、あるいはあなたを死なせようと、彼らの帰りはわれらのもとである。 (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- 彼らは言った。「私たちが死んで、土と骨になってから、本当に私たちが復活させられるというのか。」 (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- 本当に恩恵はアッラーの御手にある。かれは、御心のままにそれを与えられる。アッラーは。 (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- あなたがたは、見えないものと見えるものを知っておられる方に帰される。そしてかれは、あなたがたが行っていたことを告げられる。 (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- 信仰する者たちよ、あなたがたに対するアッラーの恩恵を思い出しなさい。その時。 (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- われらはあなた以前にも、男たちだけを遣わし、彼らに啓示を与えた。 (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- かれは彼の罪を赦し、その下を川が流れる楽園に入れる。 (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- 病気の人や旅行中の人は、他の日に（同じ日数を）補なう。 (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- 彼らはただ推測に従うのみであり、彼らはただ憶測を弄するのみである。 (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- アッラーと終末の日を望む者には、良い手本がある。 (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- われらは、天と地とその間にあるものを、真理によって創造したに過ぎない。 (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- あなたの手をあなたの懐に差し入れよ。それは何の傷もなく白く輝いて出てくるであろう。 (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- かれは、御心のままに、その慈悲を特に授けられる。アッラーは偉大な恩恵の主であられる。 (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- あなたは、アッラーが天と地の王国を支配されることを知らないのか。 (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- あなたがたが自分のために前もって送る良いものは何であれ、あなたがたはそれをアッラーの御許に見出すであろう。 (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- あなたがどこから出ても、あなたの顔を聖なるモスクの方に向けなさい。 (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- 彼らはあなた以前にも（滅び去った）。あなたはアッラーの常道に何の変更も見いだせないであろう。 (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- 天と地にあるものはすべて、かれのものである。 (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- 女性は誰でも、かれの知識なしには妊娠せず、産むこともない。 (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- かれは夜を、太陽と月を従わせられた。それぞれが定められた期間まで運行する。 (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- その下を川が流れ、彼らはそこに永遠に住む。それが報酬である。 (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- 彼は言った。「いや、あなたがたの魂があなたがたに一つのことを見せかけたのだ。だが、美しい忍耐（をせよ）。」 (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- 天と地にあるもの、そして本当にアッラーは。 (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- 彼らに使徒が来るたびに、彼らはその使徒を嘲笑していた。 (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- 彼らは言った。「ムーサーよ、あなたが投げるのか、それとも私たちが投げようか。」 (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- かれはあなたがたを死なせ、またあなたがたの中には、最も卑しい年齢に戻される者もあり、それは。 (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- 彼らには主の御許に、その下を川が流れる楽園があり、そこに永遠に住むのである。 (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- われらは彼らの心に覆いをかけ、彼らがそれを理解しないようにし、またその耳に重荷を置いた。 (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- 本当にアッラーの約束は真実である。しかし、彼らの大多数は知らない。 (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- それは彼らがアッラーとその使徒に反抗したためである。またアッラーに反抗する者は。 (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- その日、かれは彼らを呼び、「あなたがたが（わたしの）同位者と主張していた者たちはどこにいるのか」と言われる。 (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- 彼らは、アッラーが天と地を創造されたことを見なかったのか。 (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- （かれは）あなたがたを土から創造し、次に一滴の精液から、次に。 (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- 彼らは言ったであろう。「私たちの主よ、なぜあなたは私たちに使徒を遣わされなかったのですか。そうすれば私たちはあなたの印に従ったでしょうに。」 (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- そして彼らは自分たちの主に帰される。かれは彼らが行っていたことを彼らに告げられる。 (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- 彼らにはそれについての知識はなく、彼らはただ推測に従うのみである。 (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- 本当に私たちは、私たちの父祖たちがある宗教の上にあるのを見出した。そして私たちは彼らの足跡に従う者である。 (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- 啓典を与えられた者たちが、（互いに）分裂したのは、知識が彼らに来た後であった。 (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- また、イブラーヒームが言った時、「私の主よ、この町を安全なものにしてください。」 (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- かれはあなたがたに聴覚と視覚と心を与えられた。あなたがたはわずかにしか感謝しない。 (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- アッラーの印について、何の権威もなしに議論する者たち。 (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- それなら、正しい信仰のイブラーヒームの宗教に従え。彼は多神教徒ではなかった。 (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- また、われらがあなたがたを、フィルアウンの家族から救い出した時、彼らはあなたがたをひどい懲罰に苦しめていた。 (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- それが正しい宗教である。しかし、人々の大多数は知らない。 (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- あなたは、アッラーがあなたがたのために、天と地にあるものを従わせられたことを見ないのか。 (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- 不信仰者は言ったであろう。「これは明らかな魔術に過ぎない。」 (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- われらの明白な印が彼らに読誦される時、不信仰者は言う。 (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- 永遠の楽園、その下を川が流れ、彼らはそこに永遠に住む。 (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- かれは御心のままに創造される。本当にアッラーはすべてのことに全能である。 (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- あなたがたの罪を赦し、あなたがたを定められた期限まで猶予されるために。 (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- あなたがたは、私たちの先祖が崇拝していたものから私たちを遠ざけようとするのか。 (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- また、あなたの主が天使たちに言われた時、「私は粘土から人間を創造しようとしている。」 (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- かれは、その慈悲の前に、風を吉報として送られる方である。 (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- 言え、「あなたがたは地上を旅して、結末がどうなったかを観察しなさい。」 (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- 本当に天と地の創造と、夜と昼の交代の中には（印がある）。 (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- 誰がアッラーに良い貸付をするのか。そうすれば、かれはそれを何倍にもして返される。 (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- あなたは彼らの間を、アッラーが下されたものによって裁きなさい。そして彼らの欲望に従ってはならない。 (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- 彼らは、天使たちが来ることか、あるいはあなたの主の命令が来ること以外を待っているのか。 (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- 本当にアッラーに対して嘘をでっち上げる者たちは、成功しないであろう。 (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- フィルアウンの家来や、それ以前の者たちの習慣と同じように、彼らはわれらの印を嘘呼ばわりした。 (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- かれは信仰して善行に励む者たちに、彼らに報酬があるという吉報を伝える。 (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- アッラーは、御心にかなうしもべに sustenance を広げたり狭めたりされる。 (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- あなたがたは、見えないものと見えるものを知っておられる方に帰される。そしてかれは、あなたがたが行っていたことを告げられる。 (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- また、血縁者たちは、アッラーの啓典において、互いに（他の信者よりも）優先権がある。 (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
""";
